namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
    public int RatingCount => Ratings.Count;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new Recipe
        {
            Id = 1, Title = "Bruschetta", Category = "appetizers",
            Ingredients = "Baguette\nTomatoes\nFresh basil\nGarlic\nOlive oil\nBalsamic vinegar",
            Steps = "1. Slice and toast baguette\n2. Dice tomatoes, mix with chopped basil and minced garlic\n3. Drizzle with olive oil and balsamic\n4. Spoon mixture onto toast slices",
            Ratings = [4, 5, 4, 5]
        },
        new Recipe
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "appetizers",
            Ingredients = "Button mushrooms\nCream cheese\nGarlic\nParmesan\nBreadcrumbs\nParsley",
            Steps = "1. Remove mushroom stems and hollow caps\n2. Mix cream cheese, garlic, parmesan, and breadcrumbs\n3. Fill each mushroom cap with mixture\n4. Bake at 375°F for 20 minutes",
            Ratings = [5, 4, 5]
        },
        new Recipe
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "main-courses",
            Ingredients = "Spaghetti\nPancetta\nEggs\nParmesan cheese\nBlack pepper\nGarlic",
            Steps = "1. Cook spaghetti al dente\n2. Fry pancetta until crispy\n3. Whisk eggs with parmesan and pepper\n4. Toss hot pasta with pancetta, then stir in egg mixture off heat",
            Ratings = [5, 5, 4, 5, 4]
        },
        new Recipe
        {
            Id = 4, Title = "Chicken Tikka Masala", Category = "main-courses",
            Ingredients = "Chicken breast\nYogurt\nTomato sauce\nCream\nGaram masala\nCumin\nTurmeric\nGinger\nGarlic",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or bake chicken until charred\n3. Simmer tomato sauce with spices\n4. Add cream and chicken, cook 10 minutes\n5. Serve over basmati rice",
            Ratings = [5, 5, 5, 4]
        },
        new Recipe
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold in chocolate mixture and flour\n4. Pour into greased ramekins\n5. Bake at 425°F for 12 minutes\n6. Invert onto plates and serve immediately",
            Ratings = [5, 5, 5, 5, 4]
        },
        new Recipe
        {
            Id = 6, Title = "Tiramisu", Category = "desserts",
            Ingredients = "Ladyfingers\nMascarpone\nEspresso\nCocoa powder\nEggs\nSugar\nMarsala wine",
            Steps = "1. Brew espresso and let cool, add Marsala\n2. Whisk egg yolks with sugar, fold in mascarpone\n3. Whip egg whites and fold into mascarpone mixture\n4. Dip ladyfingers in espresso briefly\n5. Layer ladyfingers and cream in dish\n6. Refrigerate 4 hours, dust with cocoa",
            Ratings = [5, 4, 5]
        },
        new Recipe
        {
            Id = 7, Title = "Mango Lassi", Category = "beverages",
            Ingredients = "Mango\nYogurt\nMilk\nSugar\nCardamom",
            Steps = "1. Blend mango, yogurt, milk, sugar, and a pinch of cardamom\n2. Blend until smooth\n3. Serve chilled with ice",
            Ratings = [4, 4, 5]
        },
        new Recipe
        {
            Id = 8, Title = "Sourdough Bread", Category = "baking",
            Ingredients = "Bread flour\nWater\nSourdough starter\nSalt",
            Steps = "1. Mix flour, water, and starter; rest 30 minutes\n2. Add salt, stretch and fold every 30 min for 2 hours\n3. Shape and place in banneton\n4. Cold proof overnight in fridge\n5. Bake in Dutch oven at 450°F: 20 min covered, 20 min uncovered",
            Ratings = [5, 5, 4, 5]
        },
        new Recipe
        {
            Id = 9, Title = "Vegetable Stir Fry", Category = "vegetarian",
            Ingredients = "Broccoli\nBell peppers\nSnap peas\nCarrots\nSoy sauce\nSesame oil\nGinger\nGarlic\nTofu",
            Steps = "1. Press and cube tofu, pan-fry until golden\n2. Stir-fry vegetables in sesame oil with ginger and garlic\n3. Add soy sauce and tofu\n4. Serve over steamed rice",
            Ratings = [4, 4, 5, 4]
        }
    ];

    private int _nextId = 10;

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

@page "/recipes"
@page "/recipes/{Category}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(Category is not null ? FormatCategory(Category) : "All Recipes") - RecipeHub</PageTitle>

@if (Category is null)
{
    <h1>Browse Recipes</h1>
    <p>Select a category to explore recipes.</p>

    <div class="list-group">
        <a href="recipes/appetizers" class="list-group-item list-group-item-action">🥗 Appetizers</a>
        <a href="recipes/main-courses" class="list-group-item list-group-item-action">🍝 Main Courses</a>
        <a href="recipes/desserts" class="list-group-item list-group-item-action">🍰 Desserts</a>
        <a href="recipes/beverages" class="list-group-item list-group-item-action">🥤 Beverages</a>
        <a href="recipes/baking" class="list-group-item list-group-item-action">🍞 Baking</a>
        <a href="recipes/vegetarian" class="list-group-item list-group-item-action">🥬 Vegetarian</a>
    </div>
}
else
{
    <h1>@FormatCategory(Category)</h1>
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
            <li class="breadcrumb-item active">@FormatCategory(Category)</li>
        </ol>
    </nav>

    var recipes = RecipeService.GetByCategory(Category);
    if (recipes.Count == 0)
    {
        <p>No recipes found in this category yet.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                @if (recipe.RatingCount > 0)
                                {
                                    <span>@GetStars(recipe.AverageRating) (@recipe.RatingCount ratings)</span>
                                }
                                else
                                {
                                    <span>No ratings yet</span>
                                }
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private static string FormatCategory(string category)
    {
        return string.Join(' ', category.Split('-').Select(w =>
            char.ToUpper(w[0]) + w[1..]));
    }

    private static string GetStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="recipes" class="btn btn-primary">Browse Recipes</a>
}
else
{
    <PageTitle>@recipe.Title - RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@FormatCategory(recipe.Category)</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>

    <div class="mb-4">
        <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-5">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card mb-3">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p class="mb-2">@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }

    private static string FormatCategory(string category)
    {
        return string.Join(' ', category.Split('-').Select(w =>
            char.ToUpper(w[0]) + w[1..]));
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= hoverRating ? "hovered" : star <= displayRating ? "filled" : "")"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              @onclick="() => Rate(star)"
              role="button"
              aria-label="Rate @star stars">
            @(star <= (hoverRating > 0 ? hoverRating : displayRating) ? "★" : "☆")
        </span>
    }
    <span class="rating-info ms-2">
        @if (submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        else if (RatingCount > 0)
        {
            <span>@CurrentRating.ToString("F1") / 5 (@RatingCount ratings)</span>
        }
        else
        {
            <span>Be the first to rate!</span>
        }
    </span>
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star.filled {
        color: #ffc107;
    }
    .star-rating .star.hovered {
        color: #ffdb4d;
    }
    .star-rating .rating-info {
        font-size: 0.9rem;
        color: #666;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoverRating;
    private int displayRating;
    private bool submitted;

    protected override void OnParametersSet()
    {
        displayRating = (int)Math.Round(CurrentRating);
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
            displayRating = (int)Math.Round(CurrentRating);
        }
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (!string.IsNullOrEmpty(successMessage))
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="model.Category">
            <option value="">-- Select a category --</option>
            <option value="appetizers">Appetizers</option>
            <option value="main-courses">Main Courses</option>
            <option value="desserts">Desserts</option>
            <option value="beverages">Beverages</option>
            <option value="baking">Baking</option>
            <option value="vegetarian">Vegetarian</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="model.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(model.Title, model.Category, model.Ingredients, model.Steps);
        successMessage = $"Recipe \"{recipe.Title}\" submitted successfully!";
        model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        [System.ComponentModel.DataAnnotations.StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3-100 characters")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

