@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= hoverRating ? "hovered" : star <= displayRating ? "filled" : "")"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              @onclick="() => Rate(star)"
              role="button"
              aria-label="Rate @star stars">
            @(star <= (hoverRating > 0 ? hoverRating : displayRating) ? "★" : "☆")
        </span>
    }
    <span class="rating-info ms-2">
        @if (submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        else if (RatingCount > 0)
        {
            <span>@CurrentRating.ToString("F1") / 5 (@RatingCount ratings)</span>
        }
        else
        {
            <span>Be the first to rate!</span>
        }
    </span>
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star.filled {
        color: #ffc107;
    }
    .star-rating .star.hovered {
        color: #ffdb4d;
    }
    .star-rating .rating-info {
        font-size: 0.9rem;
        color: #666;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoverRating;
    private int displayRating;
    private bool submitted;

    protected override void OnParametersSet()
    {
        displayRating = (int)Math.Round(CurrentRating);
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
            displayRating = (int)Math.Round(CurrentRating);
        }
        submitted = true;
    }
}

